function log(action,detail,b=branch){audit.unshift({time:new Date().toLocaleString('th-TH'),role,branch:b,action,detail})}function closeModal(){$('#modal').close()}function modal(title,body){$('#modal').innerHTML=`<div class="dialoghead"><h2>${title}</h2><button aria-label="ปิดหน้าต่าง" onclick="closeModal()">✕</button></div>${body}`;$('#modal').showModal()}function field(label,name,value='',type='text',extra=''){return `<div class="field"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`}function selectField(label,name,options,value){return `<div class="field"><label for="${name}">${label}</label><select id="${name}" name="${name}">${options.map(o=>`<option value="${esc(o.id)}" ${o.id===value?'selected':''}>${esc(o.name)}</option>`).join('')}</select></div>`}function optionsBranches(){return role==='พนักงาน'||role==='ผู้จัดการสาขา'?branches.filter(b=>b.id==='b1'):branches}function scope(b){return (role==='พนักงาน'||role==='ผู้จัดการสาขา'?b==='b1':true)&&(branch==='all'||b===branch)}function branchFilter(){return `<select aria-label="กรองสาขา" onchange="branch=this.value;render()">${optionsBranches().length>1?`<option value="all">ทุกสาขา</option>`:''}${optionsBranches().map(b=>`<option value="${b.id}" ${branch===b.id?'selected':''}>${b.name}</option>`).join('')}</select>`}function table(headers,rows){return `<div class="tablewrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.join(''):`<tr><td colspan="${headers.length}" class="empty">รอข้อมูล · ยังไม่มีรายการที่ตรงกับเงื่อนไข</td></tr>`}</tbody></table></div>`}function canWrite(){return ['พนักงาน','เจ้าของ'].includes(role)}function canApprove(){return ['เจ้าของ','ผู้จัดการสาขา'].includes(role)}function canAccount(){return ['เจ้าของ','นักบัญชี'].includes(role)}function accessible(r){return scope(r.branch)}function activeTanks(b,date=day){return tanks.filter(t=>t.branch===b&&t.active&&t.start<=date)}function fuelName(id){return fuels.find(f=>f.id===id)?.name||id}function dailyRows(){return Object.values(days).filter(d=>d.date===TODAY&&scope(d.branch))}function total(key){return dailyRows().reduce((n,d)=>n+Number(d[key]||0),0)}function pending(){return requests.filter(r=>scope(r.branch)&&r.status==='รออนุมัติ')}
tasks=function(){let ds=dailyRows(),bs=optionsBranches().filter(b=>branch==='all'||b.id===branch),closed=ds.filter(d=>d.status==='ปิดวันแล้ว').length;let work=[];if(canWrite())work.push(['▧','บันทึกประจำวันของสาขา','เริ่มกรอกหรือแก้ไขรายการที่ส่งกลับ','daily']);if(canApprove())work.push(['✓',`คำขอรออนุมัติ ${pending().length} รายการ`,'ตรวจรายละเอียดและวงเงินก่อนอนุมัติ','requests'],['▧','ตรวจข้อมูลและยืนยันปิดวัน','ส่งกลับพร้อมเหตุผล หรือยืนยันเมื่อยอดครบ','daily']);if(canAccount())work.push(['฿','เงินทดรองรอเคลียร์','ตรวจหลักฐาน ยอดใช้จริง และเงินคืน','requests'],['≋','ตรวจยอดขายเทียบเงินรับ','ติดตามยอดขายเชื่อและรายการรับชำระ','finance']);if(role==='Admin')work.push(['⚙','ตั้งค่าสาขา ถัง และสิทธิ์','สิทธิ์จัดการระบบแยกจากสิทธิ์การเงิน','admin']);return head('งานของฉัน',`วันอาทิตย์ที่ 27 กันยายน 2569 · พื้นที่ทำงานของ${role}`,canWrite()?`<button class="primary" onclick="branch='b1';go('daily')">+ บันทึกประจำวัน</button>`:'')+(role==='Admin'?`<div class="note">บัญชี Admin ตัวอย่างไม่มีสิทธิ์ดูการเงิน เจ้าของในต้นแบบมีทั้งบทบาทเจ้าของและ Admin</div>`:`<div class="stats"><div class="stat"><small>สาขาที่ปิดวันแล้ว</small><strong>${closed} <span class="unit">/ ${bs.length} สาขา</span></strong><small>ประจำวันที่ 27 ก.ย. 2569</small></div><div class="stat"><small>รอตรวจข้อมูลประจำวัน</small><strong>${ds.filter(d=>d.status==='ส่งตรวจ').length} <span class="unit">สาขา</span></strong><small>ส่งต่อให้ผู้จัดการสาขา</small></div><div class="stat"><small>คำขอรออนุมัติ</small><strong>${pending().length} <span class="unit">รายการ</span></strong><small>ตรวจเงื่อนไขก่อนอนุมัติ</small></div><div class="stat"><small>เงินทดรองค้างเคลียร์</small><strong>${fmt(requests.filter(r=>scope(r.branch)&&['รอหลักฐาน','รอตรวจเคลียร์','รอจ่ายส่วนต่าง'].includes(r.status)).reduce((s,r)=>s+r.amount,0))}<span class="unit"> บาท</span></strong><small>ยังไม่ใช่ค่าใช้จ่ายที่ตรวจแล้ว</small></div></div>`)+`<div class="grid"><section class="panel"><div class="panelhead"><h2>เริ่มจากงานที่รอคุณ</h2><span class="badge">${work.length} ทางลัด</span></div>${work.map(w=>`<div class="task"><div class="taskicon">${w[0]}</div><div class="taskbody"><h3>${w[1]}</h3><small>${w[2]}</small></div><button onclick="${w[3]==='requests'?"reqFilter='all';":''}go('${w[3]}')">เปิดงาน →</button></div>`).join('')}</section><section class="panel"><h2>${role==='Admin'?'งานตั้งค่าที่ต้องเตรียม':'สถานะสาขาวันนี้'}</h2>${role==='Admin'?'<p>กำหนดถังและชนิดน้ำมันจริงก่อนเริ่มงาน</p><p>ตรวจสิทธิ์สาขาของผู้ใช้ทุกคน</p><button onclick="go(\'admin\')">เปิดจัดการระบบ →</button>':bs.map(b=>{let d=days[b.id+'|'+TODAY];return `<div class="task"><div class="taskbody"><h3>${b.name}</h3><small>${d?.updated||'ยังไม่ส่งข้อมูล'}</small><button onclick="branch='${b.id}';day=TODAY;go('daily')">ดูรายละเอียด →</button></div>${badge(d&&!d.new?d.status:'รอข้อมูล')}</div>`}).join('')}</section></div><div class="note">ขั้นตอนถัดไปจะแสดงตามบทบาท สลับบทบาทด้านบนเพื่อทดลองการส่งต่องาน · ข้อมูลเปลี่ยนเฉพาะในแท็บนี้และจะเริ่มใหม่เมื่อรีเฟรช</div>`};
function overview(){return head('ภาพรวมธุรกิจ','27 กันยายน 2569 · แสดงข้อมูลที่บันทึกแล้ว รวมรายการที่ยังไม่ปิดวัน')+`<div class="filters">${branchFilter()}</div><div class="stats"><div class="stat"><small>ยอดขายตามบันทึก</small><strong>${fmt(total('sales'))}</strong><small>บาท · รวมขายเชื่อ</small></div><div class="stat"><small>เงินรับจากยอดขายวันนี้</small><strong>${fmt(total('cash')+total('transfer')+total('card'))}</strong><small>เงินสด + โอน + บัตร</small></div><div class="stat"><small>ยอดขายเชื่อวันนี้</small><strong>${fmt(total('credit'))}</strong><small>ยังไม่หักการรับชำระหนี้</small></div><div class="stat"><small>รายจ่ายตรวจแล้ว</small><strong>${fmt(finance.filter(f=>scope(f.branch)&&f.date===TODAY&&f.type==='รายจ่าย'&&f.status==='ตรวจแล้ว').reduce((s,f)=>s+f.amount,0))}</strong><small>ไม่รวมเงินทดรองค้างเคลียร์</small></div></div><div class="grid"><section class="panel"><h2>ยอดขายแต่ละสาขา</h2><div class="chart">${optionsBranches().filter(b=>branch==='all'||branch===b.id).map(b=>{let d=days[b.id+'|'+TODAY];return `<div class="column"><b>${d?fmt(d.sales):'รอข้อมูล'}</b><div class="fill" style="height:${d?d.sales/1500:0}px;max-height:135px"></div><small>${b.name.split(' · ')[1]}</small></div>`}).join('')}</div><small>ยอดที่ยังไม่ปิดวันอาจเปลี่ยนแปลงได้ · ไม่แทนกำไรสุทธิ</small></section><section class="panel"><h2>รายการที่ต้องติดตาม</h2><div class="task"><div class="taskbody">รออนุมัติ ${pending().length} รายการ</div><button onclick="reqFilter='รออนุมัติ';go('requests')">ดูรายการ →</button></div>${optionsBranches().filter(b=>scope(b.id)&&!days[b.id+'|'+TODAY]).map(b=>`<div class="task"><div class="taskbody">${b.name}<small>ยังไม่ส่งข้อมูล</small></div><button onclick="branch='${b.id}';go('daily')">ติดตาม →</button></div>`).join('')}<div class="task"><div class="taskbody">ถังต่ำกว่าระดับแจ้งเตือน</div><button onclick="go('tanks')">ตรวจระดับถัง →</button></div></section></div>`}
function movementTotal(t,date,type){return movements.filter(m=>m.tank===t&&m.date===date&&m.type===type&&['บันทึกแล้ว','อนุมัติแล้ว'].includes(m.status)).reduce((s,m)=>s+m.liters,0)}function balance(l,date){return l.opening+movementTotal(l.tank,date,'receive')-movementTotal(l.tank,date,'use')-Number(l.sold)+Number(l.transferIn||0)-Number(l.transferOut||0)}function tankBalance(t){let d=Object.values(days).filter(d=>!d.new&&d.branch===t.branch&&d.lines.some(l=>l.tank===t.id)).sort((a,b)=>b.date.localeCompare(a.date))[0];let l=d?.lines.find(l=>l.tank===t.id);return {calc:l&&d.level==='tank'?balance(l,d.date):null,measured:l?.measured,date:d?.date,status:d?.status}}
function tanksPage(){return head('สาขาและถังน้ำมัน','ยอดจากการบันทึกล่าสุด ไม่ใช่ระดับน้ำมันสดจากอุปกรณ์')+`<div class="filters">${branchFilter()}</div><div class="tankcards">${tanks.filter(t=>scope(t.branch)).map(t=>{let v=tankBalance(t);return `<section class="panel"><div class="branchline"><small>${bname(t.branch)}</small>${badge(!t.active?'ปิดใช้งาน':v.calc!==null&&v.calc<t.warning?'น้ำมันต่ำ':v.calc===null?'รอข้อมูล':'ปกติ')}</div><h2>${t.code} · ${fuelName(t.fuel)}</h2><small>${esc(t.name)}</small><div class="tanklevel">${v.calc===null?'รอข้อมูล':fmt(v.calc)} <small>ลิตรคำนวณ</small></div><div class="bar"><span style="width:${v.calc===null?0:Math.min(100,v.calc/t.capacity*100)}%"></span></div><div class="branchline"><small>ความจุ ${fmt(t.capacity)} ลิตร</small><small>เตือนที่ ${fmt(t.warning)}</small></div><p><small>วัดจริง ${v.measured==null?'รอข้อมูล':fmt(v.measured)+' ลิตร'} · ${v.date||'ยังไม่บันทึก'}</small></p><button onclick="tankDetail('${t.id}')">ดูประวัติและรายละเอียด →</button></section>`}).join('')}</div>`}
function tankDetail(id){let t=tanks.find(t=>t.id===id),v=tankBalance(t);let ms=movements.filter(m=>m.tank===id);let d=Object.values(days).find(d=>d.lines.some(l=>l.tank===id));modal(`${t.code} · ${esc(t.name)}`,`<p>${bname(t.branch)} · ${fuelName(t.fuel)}</p><div class="note">ยอดล่าสุดจากบันทึก ${v.date||'รอข้อมูล'} · ${v.status||'ยังไม่มีบันทึก'}<br>ยอดคำนวณ ${v.calc===null?'รอข้อมูล / ยังไม่ได้แยกขายรายถัง':fmt(v.calc)+' ลิตร'} · วัดจริง ${v.measured==null?'รอข้อมูล':fmt(v.measured)+' ลิตร'}</div><h3>ประวัติการเคลื่อนไหว</h3>${table(['วันที่','รายการ','ลิตร','สถานะ'],ms.map(m=>`<tr><td>${m.date}</td><td>${m.type==='receive'?'รับเข้า':'เบิกใช้'} · ${m.id}</td><td>${fmt(m.liters)}</td><td>${badge(m.status)}</td></tr>`).concat(d?[`<tr><td>${d.date}</td><td>ขายตามบันทึกประจำวัน</td><td>${d.level==='tank'?fmt(d.lines.find(l=>l.tank===id).sold):'ยังไม่แยกถัง'}</td><td>${badge(d.status)}</td></tr>`]:[]))}<p class="muted">การปรับยอด: ยังไม่มีรายการ · การแก้ไขต้องอ้างอิงเหตุผลในประวัติ</p><button onclick="closeModal();branch='${t.branch}';go('daily')">เปิดบันทึกประจำวัน</button>`)}
function getDay(){let b=branch==='all'?'b1':branch;let key=b+'|'+day;if(!days[key])days[key]={branch:b,date:day,status:'ร่าง',level:'tank',lines:activeTanks(b).map(t=>{let previous=Object.values(days).filter(d=>d.branch===b&&d.date<day&&d.status==='ปิดวันแล้ว').sort((a,c)=>c.date.localeCompare(a.date))[0];let l=previous?.lines.find(l=>l.tank===t.id);return {tank:t.id,code:t.code,fuel:t.fuel,fuelName:fuelName(t.fuel),opening:l?balance(l,previous.date):t.opening,sold:0,measured:0,transferIn:0,transferOut:0}}),sales:0,cash:0,transfer:0,card:0,credit:0,evidence:'',note:'',updated:'ยังไม่บันทึก',fuelSales:{},new:true};return days[key]}
function dailyPage(){if(branch==='all')return head('บันทึกประจำวัน','เลือกสาขาเพื่อเริ่มกรอก ตรวจสอบ หรือดูสถานะ')+`<section class="panel">${table(['สาขา','ประจำวันที่','สถานะ','ดำเนินการ'],optionsBranches().map(b=>`<tr><td>${b.name}</td><td>${TODAY}</td><td>${badge(days[b.id+'|'+TODAY]?.status||'รอข้อมูล')}</td><td><button onclick="branch='${b.id}';day=TODAY;dailyReview=false;render()">เปิดบันทึก →</button></td></tr>`))}</section>`;let d=getDay(),editable=canWrite()&&['ร่าง','ส่งกลับแก้ไข'].includes(d.status),disabled=editable&&!dailyReview?'':'disabled',sum=d.cash+d.transfer+d.card+d.credit,locked=d.status==='ปิดวันแล้ว';return head('บันทึกประจำวัน',`${bname(branch)} · ${day}`,badge(d.status))+`<div class="filters">${branchFilter()}<input type="date" aria-label="วันที่บันทึก" value="${day}" onchange="day=this.value;dailyReview=false;render()"></div><div class="steps">${['กรอกข้อมูล','ตรวจทาน','ส่งตรวจ','ปิดวัน'].map((s,i)=>`<span class="step ${(d.status==='ปิดวันแล้ว'?3:d.status==='ส่งตรวจ'?2:dailyReview?1:0)===i?'current':''}">${i+1}. ${s}</span>`).join('')}</div>${d.reason?`<div class="note warning">เหตุผลที่ต้องตรวจสอบ: ${esc(d.reason)}</div>`:''}${locked?'<div class="note">ปิดวันแล้ว · หากต้องแก้ไข เจ้าของต้องเปิดแก้ไขพร้อมระบุเหตุผล และส่งตรวจใหม่</div>':''}${d.new?'<div class="note warning">รอข้อมูล · ยอดยกมาตัวอย่างใช้ยอดปิดวันก่อนหน้าที่มี หากไม่มี ใช้ยอดเริ่มต้นของถัง โปรดยืนยันก่อนส่งตรวจ</div>':''}<form id="dailyform" onsubmit="event.preventDefault();reviewDaily()"><section class="panel"><div class="panelhead"><h2>01 / ปริมาณน้ำมัน</h2><select aria-label="ระดับยอดขาย" style="max-width:250px" ${disabled} onchange="getDay().level=this.value;render()"><option value="tank" ${d.level==='tank'?'selected':''}>มียอดขายแยกตามถัง</option><option value="fuel" ${d.level==='fuel'?'selected':''}>มียอดขายเฉพาะชนิดน้ำมัน</option></select></div><p class="muted">รับเข้าและเบิกใช้ดึงจากรายการที่บันทึก/อนุมัติแล้ว ไม่ต้องกรอกซ้ำ</p>${d.lines.length?d.lines.map((l,i)=>`<div class="panel"><h3>${esc(l.code)} · ${esc(l.fuelName)}</h3><div class="formgrid">${field('ยอดยกมา (ลิตร)','opening'+i,l.opening,'number','disabled')}<div class="field"><label>รับเข้า / เบิกใช้ (ลิตร)</label><div class="note">+ ${fmt(movementTotal(l.tank,day,'receive'))} / − ${fmt(movementTotal(l.tank,day,'use'))}</div></div>${d.level==='tank'?field('ขายจากมิเตอร์ (ลิตร)','sold'+i,l.sold,'number',`${disabled} min="0" step="0.01" required oninput="updateLine(${i},'sold',this.value)"`):'<div class="note">ไม่ต้องเดายอดขายรายถัง ใช้ยอดขายรวมตามชนิดน้ำมันด้านล่าง</div>'}${field('วัดจริงปลายวัน (ลิตร)','measured'+i,l.measured,'number',`${disabled} min="0" max="${tanks.find(t=>t.id===l.tank)?.capacity||999999}" step="0.01" required oninput="updateLine(${i},'measured',this.value)"`)}${field('โอนเข้า (ลิตร)','tin'+i,l.transferIn||0,'number',`${disabled} min="0" step="0.01" oninput="updateLine(${i},'transferIn',this.value)"`)}${field('โอนออก (ลิตร)','tout'+i,l.transferOut||0,'number',`${disabled} min="0" step="0.01" oninput="updateLine(${i},'transferOut',this.value)"`)}</div><div id="calc${i}" class="note">${calcText(d,l)}</div></div>`).join(''):'<div class="empty">ยังไม่มีถังที่เริ่มใช้งานในวันที่เลือก ให้ Admin เพิ่มถังก่อน</div>'}${d.level==='fuel'?[...new Set(d.lines.map(l=>l.fuel))].map(f=>field(`ยอดขาย ${fuelName(f)} รวม (ลิตร)`,'fuel'+f,d.fuelSales[f]||0,'number',`${disabled} required min="0" step="0.01" oninput="getDay().fuelSales['${f}']=Number(this.value)"`)).join('')+'<div class="note warning">แสดงยอดคงเหลือและผลต่างรวมตามชนิดน้ำมันในขั้นตรวจทาน ส่วนยอดคำนวณรายถังจะแสดง “ยังไม่แยกถัง”</div>':''}</section><section class="panel"><h2>02 / ยอดขายและเงินรับ</h2><div class="formgrid">${[['ยอดขายรวม (บาท)','sales'],['เงินสด (บาท)','cash'],['เงินโอน (บาท)','transfer'],['บัตร (บาท)','card'],['ยอดขายเชื่อ (บาท)','credit']].map(([label,k])=>field(label,k,d[k],'number',`${disabled} min="0" step="0.01" required oninput="getDay()['${k}']=Number(this.value);updateMoney()"`)).join('')}</div><div id="moneycalc" class="note ${Math.abs(d.sales-sum)>.01?'warning':''}">เงินรับ + ขายเชื่อ ${fmt(sum)} บาท · ผลต่างจากยอดขาย ${fmt(d.sales-sum)} บาท</div><div class="field"><label for="dnote">หมายเหตุ / เหตุผลผลต่างน้ำมัน</label><textarea id="dnote" ${disabled} oninput="getDay().note=this.value">${esc(d.note)}</textarea></div><div class="field"><label for="devidence">หลักฐาน (จำลองการเลือกไฟล์ ไม่อัปโหลด)</label><input id="devidence" type="file" accept="image/*,.pdf" ${disabled} onchange="getDay().evidence=this.files[0]?.name||getDay().evidence;document.querySelector('#evidenceName').textContent=getDay().evidence"><small id="evidenceName">${esc(d.evidence||'ยังไม่ได้เลือกหลักฐาน')}</small></div></section>${dailyReview?`<section class="panel"><h2>ตรวจทานก่อนส่ง</h2><p>สาขา ${bname(d.branch)} · ${day} · ยอดขาย ${fmt(d.sales)} บาท</p>${d.level==='fuel'?fuelSummary(d):''}<p>หลักฐาน: ${esc(d.evidence||'ไม่มี')}</p><p>ส่งต่อให้ผู้จัดการสาขาตรวจสอบและยืนยันปิดวัน</p></section>`:''}<div id="saveError"></div><div class="footactions"><small>บันทึกล่าสุด: ${d.updated}</small><div class="actions">${editable?dailyReview?'<button type="button" onclick="dailyReview=false;render()">กลับไปแก้ไข</button><button type="button" class="primary" onclick="saveDaily(\'ส่งตรวจ\')">ยืนยันส่งตรวจ</button>':'<button type="button" onclick="saveDaily(\'ร่าง\')">บันทึกร่าง</button><button type="submit" class="primary">ตรวจทานก่อนส่ง →</button>':''}${canApprove()&&d.status==='ส่งตรวจ'?'<button type="button" class="danger" onclick="returnDaily()">ส่งกลับแก้ไข</button><button type="button" class="primary" onclick="closeDay()">ยืนยันปิดวัน</button>':''}${role==='เจ้าของ'&&locked?'<button type="button" onclick="reopenDay()">เปิดแก้ไขย้อนหลัง</button>':''}</div></div></form>`}
function calcText(d,l){return d.level==='tank'?`คงเหลือคำนวณ ${fmt(balance(l,d.date))} ลิตร · ผลต่างวัดจริง − คำนวณ ${fmt(l.measured-balance(l,d.date))} ลิตร`:'ยอดคำนวณรายถัง: ยังไม่แยกถัง'}function updateLine(i,k,v){let d=getDay();d.lines[i][k]=Number(v);$('#calc'+i).textContent=calcText(d,d.lines[i])}function updateMoney(){let d=getDay();$('#moneycalc').textContent=`เงินรับ + ขายเชื่อ ${fmt(d.cash+d.transfer+d.card+d.credit)} บาท · ผลต่างจากยอดขาย ${fmt(d.sales-d.cash-d.transfer-d.card-d.credit)} บาท`}function fuelSummary(d){return [...new Set(d.lines.map(l=>l.fuel))].map(f=>{let ls=d.lines.filter(l=>l.fuel===f),bal=ls.reduce((s,l)=>s+l.opening+movementTotal(l.tank,d.date,'receive')-movementTotal(l.tank,d.date,'use')+l.transferIn-l.transferOut,0)-(d.fuelSales[f]||0),actual=ls.reduce((s,l)=>s+l.measured,0);return `<div class="note">${fuelName(f)} · คงเหลือรวม ${fmt(bal)} ลิตร · วัดจริง ${fmt(actual)} · ผลต่าง ${fmt(actual-bal)}</div>`}).join('')}
function validateDaily(){let d=getDay();if(!d.lines.length)return 'ยังไม่มีถังที่ใช้งานในวันที่เลือก';if(Math.abs(d.sales-d.cash-d.transfer-d.card-d.credit)>.01)return 'เงินสด + โอน + บัตร + ขายเชื่อ ต้องเท่ากับยอดขาย โปรดตรวจยอดอีกครั้ง';if(d.lines.some(l=>d.level==='tank'&&balance(l,d.date)<0))return 'ยอดคงเหลือติดลบ โปรดตรวจยอดขายและยอดยกมา';if(!d.evidence)return 'กรุณาเลือกหลักฐานรายงานยอดขาย';if(d.lines.some(l=>Math.abs(l.measured-balance(l,d.date))>.01)&&!d.note.trim())return 'โปรดระบุหมายเหตุเพื่ออธิบายผลต่างน้ำมัน';return ''}function reviewDaily(){let err=validateDaily();if(err){$('#saveError').innerHTML=`<div class="note error" role="alert">${err} · ข้อมูลที่กรอกยังอยู่</div>`;return}dailyReview=true;render()}
function simulateSave(action){const f=$('#saveError');if(f)f.innerHTML='<div class="note" role="status">กำลังบันทึก… โปรดรอสักครู่</div>';document.querySelectorAll('.footactions button').forEach(b=>b.disabled=true);setTimeout(()=>{if(failNext){failNext=false;if(f)f.innerHTML='<div class="note error" role="alert">บันทึกไม่สำเร็จ (สถานการณ์จำลอง) ข้อมูลที่กรอกยังอยู่ในแท็บนี้ อย่าปิดหรือรีเฟรชหน้า กดบันทึกอีกครั้ง หรือคัดลอกข้อความเก็บไว้</div>';document.querySelectorAll('.footactions button').forEach(b=>b.disabled=false);toast('จำลองการบันทึกล้มเหลว · ลองใหม่ได้');}else action()},700)}function saveDaily(status){let d=getDay();if(!canWrite()||!['ร่าง','ส่งกลับแก้ไข'].includes(d.status))return toast('รายการนี้ส่งตรวจแล้ว ไม่สามารถส่งซ้ำได้');if(status==='ส่งตรวจ'){let e=validateDaily();if(e)return toast(e)}simulateSave(()=>{let before=d.status;d.status=status;d.updated=new Date().toLocaleString('th-TH');delete d.new;log('บันทึกประจำวัน',`${day}: ${before} → ${status}`,d.branch);dailyReview=false;render();toast(status==='ส่งตรวจ'?'ส่งให้ผู้จัดการสาขาตรวจสอบแล้ว':'บันทึกร่างในต้นแบบแล้ว')})}function reasonModal(title,action){modal(title,`<form onsubmit="event.preventDefault();${action}(this.reason.value)"><div class="field"><label for="reason">เหตุผล (จำเป็น)</label><textarea id="reason" name="reason" required minlength="5"></textarea></div><button class="primary">ยืนยันพร้อมเหตุผล</button></form>`)}function returnDaily(){reasonModal('ส่งกลับให้พนักงานแก้ไข','doReturnDaily')}function doReturnDaily(reason){let d=getDay();d.status='ส่งกลับแก้ไข';d.reason=reason;log('ส่งกลับแก้ไข',reason,d.branch);closeModal();render()}function closeDay(){let d=getDay();modal('ยืนยันปิดวัน',`<p>${bname(d.branch)} · ${day}</p><p>ยอดขาย ${fmt(d.sales)} บาท · หลักฐาน ${esc(d.evidence)}</p><p>หลังยืนยัน พนักงานจะแก้ไขไม่ได้จนกว่าจะเปิดแก้ไขพร้อมเหตุผล</p><button class="primary" onclick="confirmCloseDay()">ตรวจครบแล้ว ยืนยันปิดวัน</button>`)}function confirmCloseDay(){let d=getDay();if(!canApprove()||d.status!=='ส่งตรวจ')return;d.status='ปิดวันแล้ว';d.reason='';d.updated=new Date().toLocaleString('th-TH');log('ยืนยันปิดวัน',`${day} · ส่งตรวจ → ปิดวันแล้ว`,d.branch);closeModal();render();toast('ปิดวันเรียบร้อยแล้ว')}function reopenDay(){reasonModal('เปิดแก้ไขย้อนหลังโดยเจ้าของ','doReopenDay')}function doReopenDay(reason){let d=getDay();d.previousVersions??=[];d.previousVersions.push(JSON.parse(JSON.stringify({...d,previousVersions:undefined})));d.status='ส่งกลับแก้ไข';d.reason=reason;log('เปิดแก้ไขย้อนหลัง',`${day} · ${reason} · เก็บข้อมูลก่อนแก้ไขแล้ว`,d.branch);closeModal();render()}
function movementPage(type){let incoming=type==='receive';return head(incoming?'รับน้ำมันเข้า':'เบิกใช้น้ำมัน',incoming?'บันทึกครั้งเดียว เชื่อมยอดรับเข้ากับสรุปประจำวัน':'รายการที่อนุมัติแล้วจึงหักจากยอดน้ำมันประจำวัน',canWrite()?`<button class="primary" onclick="movementForm('${type}')">+ ${incoming?'รับน้ำมันเข้า':'ขอเบิกใช้น้ำมัน'}</button>`:'')+`<div class="filters">${branchFilter()}</div><section class="panel">${table(['เลขที่ / วันที่','สาขา / ถัง','ปริมาณ','สถานะ','รายละเอียด'],movements.filter(m=>m.type===type&&scope(m.branch)).map(m=>`<tr><td>${m.id}<br><small>${m.date}</small></td><td>${bname(m.branch)}<br><small>${tanks.find(t=>t.id===m.tank)?.code}</small></td><td>${fmt(m.liters)} ลิตร</td><td>${badge(m.status)}</td><td><button onclick="movementDetail('${m.id}')">เปิดรายการ</button></td></tr>`))}</section>`}
function movementForm(type){let b=branch==='all'?'b1':branch;modal(type==='receive'?'รับน้ำมันเข้า':'ขอเบิกใช้น้ำมัน',`<form onsubmit="event.preventDefault();saveMovement(this,'${type}')"><div class="formgrid">${selectField('สาขา','branch',optionsBranches(),b)}${field('วันที่','date',TODAY,'date','required')}${selectField('ถัง','tank',tanks.filter(t=>t.active).map(t=>({id:t.id,name:bname(t.branch)+' / '+t.code+' '+fuelName(t.fuel)})),activeTanks(b)[0]?.id)}${field('ปริมาณ (ลิตร)','liters','','number','required min="0.01" step="0.01"')}${field(type==='receive'?'ผู้จำหน่าย':'ผู้เบิก','person','','text','required')}${field(type==='receive'?'เลขที่เอกสาร':'รถหรืออุปกรณ์','doc','','text','required')}${field('รายละเอียด / วัตถุประสงค์','purpose','','text','required')}<div class="field"><label for="movfile">หลักฐานจำลอง</label><input id="movfile" name="evidence" type="file" accept="image/*,.pdf" required></div></div><div class="note">เลือกถังของสาขาให้ตรงกัน รายการในวันปิดแล้วต้องเปิดแก้ไขก่อน</div><div id="movError"></div><button class="primary">${type==='receive'?'บันทึกรับเข้า':'ส่งขออนุมัติ'}</button></form>`)}function saveMovement(form,type){let x=Object.fromEntries(new FormData(form));let t=tanks.find(t=>t.id===x.tank);let err=t.branch!==x.branch?'ถังนี้ไม่ได้อยู่ในสาขาที่เลือก':t.start>x.date?'ถังยังไม่เริ่มใช้งานในวันที่เลือก':['ปิดวันแล้ว','ส่งตรวจ'].includes(days[x.branch+'|'+x.date]?.status)?'วันดังกล่าวปิดหรือส่งตรวจแล้ว กรุณาส่งกลับ/เปิดแก้ไขก่อน':movements.some(m=>type==='receive'&&m.type===type&&m.branch===x.branch&&m.doc===x.doc)?'เลขที่เอกสารนี้มีแล้ว กรุณาตรวจรายการซ้ำ':'';if(err){$('#movError').innerHTML=`<div class="note error">${err}</div>`;return}let m={...x,id:(type==='receive'?'IN-':'USE-')+String(movements.length+1).padStart(3,'0'),type,liters:Number(x.liters),evidence:form.evidence.files[0]?.name||'',status:type==='receive'?'บันทึกแล้ว':'รออนุมัติ'};movements.push(m);log('เพิ่มรายการน้ำมัน',m.id+' · '+m.liters+' ลิตร',m.branch);closeModal();render();toast('บันทึกจำลองแล้ว · สรุปประจำวันอัปเดตจากรายการเดียวกัน')}
function movementDetail(id){let m=movements.find(m=>m.id===id);modal(m.id,`<p>${bname(m.branch)} · ${m.date}</p><h3>${fmt(m.liters)} ลิตร ${badge(m.status)}</h3><p>${esc(m.person)} · ${esc(m.purpose)}</p><p>เอกสาร / อุปกรณ์: ${esc(m.doc||m.vehicle||'—')}</p><p>หลักฐาน: ${esc(m.evidence)} (ชื่อไฟล์จำลอง)</p>${m.status==='รออนุมัติ'&&canApprove()?`<button class="primary" onclick="approveMovement('${id}')">อนุมัติเบิกใช้น้ำมัน</button>`:''}`)}function approveMovement(id){let m=movements.find(m=>m.id===id);if(['ปิดวันแล้ว','ส่งตรวจ'].includes(days[m.branch+'|'+m.date]?.status))return toast('บันทึกวันนั้นถูกล็อก ต้องส่งกลับหรือเปิดแก้ไขก่อน');m.status='อนุมัติแล้ว';log('อนุมัติเบิกน้ำมัน',id,m.branch);closeModal();render()}
function requestsPage(){let list=requests.filter(r=>scope(r.branch)&&(reqFilter==='all'||r.status===reqFilter));return head('เบิกเงินและอนุมัติ','ติดตามตั้งแต่ขอเบิก จ่ายเงิน จนส่งหลักฐานและปิดรายการ',canWrite()?'<button class="primary" onclick="requestForm()">+ ขอเบิกเงิน</button>':'')+`<div class="filters">${branchFilter()}<select aria-label="สถานะคำขอ" onchange="reqFilter=this.value;render()">${['all','ร่าง','รออนุมัติ','อนุมัติแล้ว','รอหลักฐาน','รอตรวจเคลียร์','รอจ่ายส่วนต่าง','ปิดรายการ','ปฏิเสธ','ส่งกลับแก้ไข'].map(s=>`<option value="${s}" ${reqFilter===s?'selected':''}>${s==='all'?'ทุกสถานะ':s}</option>`).join('')}</select></div><div class="note">ตัวอย่าง REQ-002: เบิก 2,000 บาท → ใช้จริง 1,850 บาท → คืน 150 บาท เงินทดรองจะเป็นค่าใช้จ่ายเพียงครั้งเดียวหลังตรวจเคลียร์</div><section class="panel">${table(['คำขอ / ผู้ขอ','สาขา / วัตถุประสงค์','ยอดขอเบิก','สถานะ','ดำเนินการ'],list.map(r=>`<tr><td>${r.id}<br><small>${r.person}</small></td><td>${bname(r.branch)}<br><small>${esc(r.purpose)}</small></td><td>${fmt(r.amount)} บาท</td><td>${badge(r.status)}</td><td><button onclick="requestDetail('${r.id}')">เปิดคำขอ →</button></td></tr>`))}</section>`}
function requestForm(id){let r=requests.find(r=>r.id===id);modal(r?'แก้ไขคำขอ':'ขอเบิกเงิน',`<form onsubmit="event.preventDefault();saveRequest(this,'${id||''}',event.submitter.value)"><div class="formgrid">${selectField('สาขา','branch',optionsBranches(),r?.branch||(branch==='all'?'b1':branch))}${field('วันที่','date',r?.date||TODAY,'date','required')}${field('ชื่อผู้ขอ','person',r?.person||'คุณเมย์','text','required')}${field('จำนวนเงิน (บาท)','amount',r?.amount||2000,'number','min="1" step="0.01" required')}${selectField('หมวดค่าใช้จ่าย','category',categories.filter(c=>c.active).map(c=>({id:c.name,name:c.name})),r?.category||'ค่าซ่อมบำรุง')}${field('วัตถุประสงค์','purpose',r?.purpose||'','text','required')}</div><div class="field"><label>เอกสารประกอบคำขอ (ถ้ามี)</label><input name="attachment" type="file" accept="image/*,.pdf"></div><div class="note">ผู้อนุมัติตัวอย่าง: ผู้จัดการไม่เกิน 3,000 บาท / เจ้าของไม่เกิน 100,000 บาท</div><button name="mode" value="ร่าง">บันทึกร่าง</button> <button class="primary" name="mode" value="รออนุมัติ">ส่งอนุมัติ</button></form>`)}function saveRequest(form,id,mode){let r=requests.find(r=>r.id===id),x=Object.fromEntries(new FormData(form)),status=mode||'รออนุมัติ';if(Number(x.amount)>100000)return toast('เกินวงเงินอนุมัติตัวอย่าง 100,000 บาท');if(r&&!['ร่าง','ส่งกลับแก้ไข'].includes(r.status))return;let payload={...x,amount:Number(x.amount),status,attachment:form.attachment.files[0]?.name||r?.attachment||''};delete payload.mode;if(r)Object.assign(r,payload);else{r={...payload,id:'REQ-'+String(requests.length+1).padStart(3,'0'),actual:0,returned:0,evidence:'',history:[]};requests.push(r)}r.history.push(role+' · '+status);log('คำขอเบิกเงิน',r.id+' → '+status,r.branch);closeModal();render();toast('บันทึกคำขอในต้นแบบแล้ว')}
function requestDetail(id){let r=requests.find(r=>r.id===id),actions='';if(canWrite()&&['ร่าง','ส่งกลับแก้ไข'].includes(r.status))actions=`<button class="primary" onclick="requestForm('${id}')">แก้ไขและส่งใหม่</button>`;if(canApprove()&&r.status==='รออนุมัติ')actions=`<button class="primary" ${role==='ผู้จัดการสาขา'&&r.amount>3000?'disabled':''} onclick="transitionRequest('${id}','อนุมัติแล้ว')">อนุมัติคำขอ</button><button class="danger" onclick="rejectRequest('${id}')">ปฏิเสธพร้อมเหตุผล</button><small>${role==='ผู้จัดการสาขา'?'วงเงินผู้จัดการไม่เกิน 3,000 บาท':''}</small>`;if(canAccount()&&r.status==='อนุมัติแล้ว')actions=`<button class="primary" onclick="paymentForm('${id}')">บันทึกจ่ายเงิน</button>`;if(canWrite()&&r.status==='รอหลักฐาน')actions=`<button class="primary" onclick="settlementForm('${id}')">ส่งหลักฐานและยอดใช้จริง</button>`;if(canAccount()&&r.status==='รอตรวจเคลียร์')actions=`<button class="primary" onclick="completeRequest('${id}')">ตรวจครบแล้ว ${r.actual>r.amount?'ส่งจ่ายส่วนต่าง':'ปิดรายการ'}</button><button onclick="settlementReturn('${id}')">ส่งกลับแก้ไขหลักฐาน</button>`;if(canAccount()&&r.status==='รอจ่ายส่วนต่าง')actions=`<button class="primary" onclick="paymentForm('${id}',true)">บันทึกจ่ายเพิ่ม ${fmt(r.actual-r.amount)} บาท</button>`;modal(`คำขอ ${id}`,`<div class="steps">${['ขอเบิก','อนุมัติ','จ่ายเงิน','ส่งหลักฐาน','ตรวจปิด'].map((s,i)=>`<span class="step ${(['ร่าง','รออนุมัติ','อนุมัติแล้ว','รอหลักฐาน','รอตรวจเคลียร์','ปิดรายการ'].indexOf(r.status)-1)===i?'current':''}">${s}</span>`).join('')}</div><p>${bname(r.branch)} · ${esc(r.person)} · ${r.date}</p><h2>${esc(r.purpose)} ${badge(r.status)}</h2><div class="kpirow"><span>ยอดขอเบิก</span><b>${fmt(r.amount)} บาท</b></div><div class="kpirow"><span>ใช้จริงตามหลักฐาน</span><b>${r.evidence?fmt(r.actual)+' บาท':'รอหลักฐาน'}</b></div><div class="kpirow"><span>เงินคืน / จ่ายเพิ่ม</span><b>${r.evidence?r.actual<=r.amount?'คืน '+fmt(r.returned)+' บาท':'จ่ายเพิ่ม '+fmt(r.actual-r.amount)+' บาท':'รอข้อมูล'}</b></div><p>หลักฐาน: ${esc(r.evidence||r.attachment||'ยังไม่ได้ส่ง')}</p>${r.reason?`<div class="note warning">${esc(r.reason)}</div>`:''}<div class="note">${r.status==='ปิดรายการ'?'งานเสร็จแล้ว · ลงรายจ่ายใช้จริงครั้งเดียว':'งานถัดไป: '+({'รออนุมัติ':'ผู้มีสิทธิ์อนุมัติตรวจคำขอ','อนุมัติแล้ว':'นักบัญชีบันทึกจ่าย','รอหลักฐาน':'ผู้ขอส่งยอดใช้จริงและหลักฐาน','รอตรวจเคลียร์':'นักบัญชีตรวจหลักฐานและเงินคืน','รอจ่ายส่วนต่าง':'นักบัญชีจ่ายส่วนต่าง','ปฏิเสธ':'สิ้นสุดคำขอ สามารถสร้างคำขอใหม่ได้'}[r.status]||'ผู้ขอแก้ไขและส่งอนุมัติ')}</div><div class="actions">${actions}</div><h3 style="margin-top:24px">ประวัติคำขอ</h3>${r.history.map(h=>`<div class="timeline">${esc(h)}</div>`).join('')}`)}
function transitionRequest(id,status){let r=requests.find(r=>r.id===id);r.status=status;r.history.push(role+' · '+status);log('เปลี่ยนสถานะคำขอ',`${id} → ${status}`,r.branch);closeModal();render();requestDetail(id)}let actingRequest='';function rejectRequest(id){actingRequest=id;reasonModal('ปฏิเสธคำขอ','doReject')}function doReject(reason){requests.find(r=>r.id===actingRequest).reason=reason;transitionRequest(actingRequest,'ปฏิเสธ')}function paymentForm(id,extra=false){let r=requests.find(r=>r.id===id);modal(extra?'บันทึกจ่ายส่วนต่าง':'บันทึกจ่ายเงินทดรอง',`<form onsubmit="event.preventDefault();recordPayment(this,'${id}',${extra})"><h2>${fmt(extra?r.actual-r.amount:r.amount)} บาท</h2>${field('วันที่จ่าย','date',TODAY,'date','required')}${selectField('ช่องทางจ่าย','channel',[{id:'เงินโอน',name:'เงินโอน'},{id:'เงินสด',name:'เงินสด'}],'เงินโอน')}${field('เลขที่อ้างอิงการจ่าย','ref','','text','required')}<div class="field"><label>หลักฐานการจ่าย (จำลอง)</label><input name="evidence" type="file" required></div><div class="note">จ่ายเงินทดรองยังไม่ลงเป็นค่าใช้จ่าย จนกว่าจะตรวจยอดใช้จริง</div><button class="primary">ยืนยันบันทึกจ่ายเงิน</button></form>`)}function recordPayment(form,id,extra){let r=requests.find(r=>r.id===id);r.payment={date:form.date.value,channel:form.channel.value,ref:form.ref.value,evidence:form.evidence.files[0].name};if(extra){r.status='ปิดรายการ';postExpense(r);r.history.push('นักบัญชีจ่ายส่วนต่างและปิดรายการ');closeModal();render();toast('จ่ายส่วนต่างและปิดรายการแล้ว')}else transitionRequest(id,'รอหลักฐาน');log('บันทึกการจ่าย',id+' · '+(extra?r.actual-r.amount:r.amount)+' บาท',r.branch)}
function settlementForm(id){let r=requests.find(r=>r.id===id);modal('ส่งหลักฐานและเคลียร์เงินทดรอง',`<form onsubmit="event.preventDefault();saveSettlement(this,'${id}')"><p>รับเงินทดรอง ${fmt(r.amount)} บาท</p>${field('ยอดใช้จริง (บาท)','actual',r.actual||1850,'number',`required min="0" step="0.01" oninput="document.querySelector('#settlediff').textContent='ส่วนต่าง '+(${r.amount}-Number(this.value)).toLocaleString('th-TH')+' บาท (บวก = คืน / ลบ = จ่ายเพิ่ม)'"`)}<div id="settlediff" class="note">ส่วนต่าง ${fmt(r.amount-(r.actual||1850))} บาท (บวก = คืน / ลบ = จ่ายเพิ่ม)</div>${field('คืนเงินแล้ว (บาท)','returned',r.returned||150,'number','required min="0" step="0.01"')}<div class="field"><label>ใบเสร็จใช้จริง</label><input name="evidence" type="file" required></div><div class="field"><label>หลักฐานเงินคืน (จำเป็นเมื่อมีเงินคืน)</label><input name="returnEvidence" type="file"></div>${field('คำอธิบาย','note',r.reason||'','text')}<div id="settleError"></div><button class="primary">ส่งให้นักบัญชีตรวจ</button></form>`)}function saveSettlement(form,id){let r=requests.find(r=>r.id===id),actual=Number(form.actual.value),returned=Number(form.returned.value);if(Math.abs(returned-Math.max(0,r.amount-actual))>.01||returned>0&&!form.returnEvidence.files.length){$('#settleError').innerHTML='<div class="note error">ยอดเงินคืนต้องเท่ากับยอดเบิก − ใช้จริง และต้องแนบหลักฐานเงินคืน ถ้าใช้เกิน ให้คืน 0 บาท</div>';return}Object.assign(r,{actual,returned,evidence:form.evidence.files[0].name,returnEvidence:form.returnEvidence.files[0]?.name||'',reason:form.note.value});transitionRequest(id,'รอตรวจเคลียร์')}function postExpense(r){if(!finance.some(f=>f.source===r.id))finance.push({id:'FIN-'+String(finance.length+1).padStart(3,'0'),source:r.id,branch:r.branch,date:TODAY,type:'รายจ่าย',category:r.category,amount:r.actual,person:r.person,channel:'เคลียร์เงินทดรอง',detail:r.purpose,evidence:r.evidence,recorder:'นักบัญชี',status:'ตรวจแล้ว'})}function completeRequest(id){let r=requests.find(r=>r.id===id);if(r.actual>r.amount)return transitionRequest(id,'รอจ่ายส่วนต่าง');postExpense(r);transitionRequest(id,'ปิดรายการ')}function settlementReturn(id){actingRequest=id;reasonModal('ส่งกลับให้แก้ไขหลักฐาน','doSettlementReturn')}function doSettlementReturn(reason){requests.find(r=>r.id===actingRequest).reason=reason;transitionRequest(actingRequest,'รอหลักฐาน')}
function financePage(){let rows=finance.filter(f=>scope(f.branch)&&(!finFilter||(f.person+f.detail+f.id).includes(finFilter))&&(!finDate||f.date===finDate)&&(!finCategory||f.category===finCategory)&&(!finStatus||f.status===finStatus));return head('รายรับ–รายจ่าย','ตรวจยอดเงิน แยกรายจ่ายและการรับชำระหนี้ออกจากยอดขาย',canAccount()?'<button class="primary" onclick="financeForm()">+ เพิ่มรายการ</button>':'')+`<div class="filters">${branchFilter()}<input aria-label="ค้นหารายการ" placeholder="ค้นหาเลขที่ ชื่อ หรือรายละเอียด" value="${esc(finFilter)}" onchange="finFilter=this.value;render()"><input aria-label="กรองวันที่" type="date" value="${finDate}" onchange="finDate=this.value;render()"><select aria-label="กรองหมวด" onchange="finCategory=this.value;render()"><option value="">ทุกหมวด</option>${categories.map(c=>`<option ${c.name===finCategory?'selected':''}>${c.name}</option>`).join('')}</select><select aria-label="กรองสถานะ" onchange="finStatus=this.value;render()"><option value="">ทุกสถานะ</option>${['รอตรวจ','ตรวจแล้ว'].map(s=>`<option ${s===finStatus?'selected':''}>${s}</option>`).join('')}</select></div><section class="panel"><h2>กระทบยอดจากบันทึกประจำวันที่ 27 ก.ย.</h2>${table(['สาขา','ยอดขาย','รับเงินแล้ว','ขายเชื่อ','รับชำระหนี้','คงค้าง'],dailyRows().map(d=>{let paid=finance.filter(f=>f.branch===d.branch&&f.type==='รับชำระหนี้'&&f.status==='ตรวจแล้ว').reduce((s,f)=>s+f.amount,0);return `<tr><td>${bname(d.branch)}</td><td>${fmt(d.sales)}</td><td>${fmt(d.cash+d.transfer+d.card)}</td><td>${fmt(d.credit)}</td><td>${fmt(paid)}</td><td>${fmt(d.credit-paid)}</td></tr>`}))}<small>รับชำระหนี้ตัวอย่างผูกกับยอดขายเชื่อวันที่ 27 ก.ย. · ไม่เพิ่มยอดขายซ้ำ</small></section><section class="panel">${table(['วันที่ / เลขที่','สาขา / หมวด','ประเภท','จำนวนเงิน','สถานะ',''],rows.map(f=>`<tr><td>${f.date}<br><small>${f.id}</small></td><td>${bname(f.branch)}<br><small>${esc(f.category)}</small></td><td>${f.type}</td><td>${fmt(f.amount)}</td><td>${badge(f.status)}</td><td><button onclick="financeDetail('${f.id}')">เปิดรายการ</button></td></tr>`))}</section><div class="note">ยอดขายมาจากบันทึกประจำวันเท่านั้น · เงินโอนภายในไม่ใช่รายรับหรือรายจ่าย · เงินรับลบเงินจ่ายเป็นกระแสเงินสด ไม่เรียกว่า “กำไรสุทธิ”</div>`}
function financeForm(id){let f=finance.find(f=>f.id===id);modal(f?'แก้ไขรายรับ–รายจ่าย':'เพิ่มรายรับ–รายจ่าย',`<form onsubmit="event.preventDefault();saveFinance(this,'${id||''}')"><div class="formgrid">${selectField('สาขา','branch',optionsBranches(),f?.branch||(branch==='all'?'b1':branch))}${field('วันที่','date',f?.date||TODAY,'date','required')}${selectField('ประเภท','type',['รายจ่าย','รายรับอื่น','รับชำระหนี้','เงินโอนภายใน'].map(s=>({id:s,name:s})),f?.type||'รายจ่าย')}${selectField('หมวด','category',categories.filter(c=>c.active).map(c=>({id:c.name,name:c.name})),f?.category||'อื่น ๆ')}${field('จำนวนเงิน (บาท)','amount',f?.amount||'','number','required min="0.01" step="0.01"')}${field('ผู้รับ / ผู้จ่าย','person',f?.person||'','text','required')}${selectField('ช่องทาง','channel',['เงินสด','เงินโอน','บัตร'].map(s=>({id:s,name:s})),f?.channel||'เงินโอน')}${field('รายละเอียด / เลขที่อ้างอิง','detail',f?.detail||'','text','required')}</div><div class="field"><label>หลักฐาน ${f?'(เลือกใหม่เมื่อเปลี่ยน)':''}</label><input name="evidence" type="file" ${f?'':'required'}></div><div class="note">รับชำระหนี้: ใช้ยอดเชื่อของวันที่ 27 ก.ย. ในต้นแบบ · โอนภายใน: บันทึกครั้งเดียวเพื่อไม่สร้างรายจ่ายซ้ำ</div><button class="primary">บันทึกและส่งตรวจ</button></form>`)}function saveFinance(form,id){let x=Object.fromEntries(new FormData(form)),f=finance.find(f=>f.id===id);x.amount=Number(x.amount);x.evidence=form.evidence.files[0]?.name||f?.evidence||'';x.recorder=role;x.status='รอตรวจ';if(x.type==='รับชำระหนี้'){let owing=(days[x.branch+'|'+TODAY]?.credit||0)-finance.filter(a=>a.id!==id&&a.branch===x.branch&&a.type==='รับชำระหนี้').reduce((s,a)=>s+a.amount,0);if(x.amount>owing)return toast('ยอดรับชำระเกินยอดขายเชื่อคงค้าง')}if(f)Object.assign(f,x);else finance.push({...x,id:'FIN-'+String(finance.length+1).padStart(3,'0')});log('บันทึกรายรับ–รายจ่าย',`${x.type} ${x.amount} บาท`,x.branch);closeModal();render()}function financeDetail(id){let f=finance.find(f=>f.id===id);modal(id,`<p>${bname(f.branch)} · ${f.date} ${badge(f.status)}</p><h2>${f.type} · ${fmt(f.amount)} บาท</h2><p>หมวด: ${esc(f.category)} · ${esc(f.person)}</p><p>ช่องทาง: ${esc(f.channel)}</p><p>${esc(f.detail)}</p><p>หลักฐาน: ${esc(f.evidence)} (ชื่อไฟล์จำลอง)</p><p>ผู้บันทึก: ${esc(f.recorder)} ${f.source?'· อ้างอิง '+f.source:''}</p><div class="actions">${canAccount()&&!f.source?`<button onclick="financeForm('${id}')">แก้ไขรายการ</button>`:''}${canAccount()&&f.status==='รอตรวจ'?`<button class="primary" onclick="verifyFinance('${id}')">ตรวจสอบแล้ว</button>`:''}</div>${f.source?'<div class="note">รายการนี้สร้างจากยอดใช้จริงของเงินทดรอง แก้ผ่านกระบวนการเคลียร์เพื่อป้องกันนับซ้ำ</div>':''}`)}function verifyFinance(id){let f=finance.find(f=>f.id===id);f.status='ตรวจแล้ว';log('ตรวจรายรับ–รายจ่าย',id,f.branch);closeModal();render()}
